const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const r=$input.first().json||{};
const f=r.fields||r;
const clientBase=String(f['Clayroots Base ID']||'').trim();
const raw=String(f['Intent Tables']||'');
const lines=raw.split('\n').map(s=>s.trim()).filter(Boolean);
const tables=[];
for(const ln of lines){
  let t=ln;
  if(ln.includes('/')){ const parts=ln.split('/').map(s=>s.trim()).filter(Boolean); t=parts.find(p=>/^tbl/.test(p))||''; }
  if(/^tbl/.test(t) && clientBase) tables.push({ baseId: clientBase, tableId: t });
}
const clientRecId=r.id||'';
const clientName=f['Client']||'';
if(!tables.length) return [{ json: { clientRecId, clientName, baseId:'', tableId:'' } }];
return tables.map(t=>({ json: { clientRecId, clientName, baseId:t.baseId, tableId:t.tableId } }));

let tables=[]; try{ tables=$('Parse Client Config').all().map(i=>i.json).filter(t=>t&&t.baseId); }catch(e){}
const rows=$input.all();
const out=[];
for(const it of rows){
  const j=it.json||{};
  let src=null;
  try{ const pi=it.pairedItem; const idx=(typeof pi==='number')?pi:(pi&&pi.item); if(idx!==undefined&&idx!==null) src=tables[idx]||null; }catch(e){}
  if(!src && tables.length===1) src=tables[0];
  if(!src) src=tables[0]||{};
  if(j.error){ out.push({ json: { _readError:true, tableId:src.tableId||'', errorMessage:String((j.error&&(j.error.message||j.error))||'read failed').slice(0,160) } }); continue; }
  if(!j.id) continue;
  out.push({ json: { recordId:j.id, baseId:src.baseId||'', tableId:src.tableId||'', clientRecId:src.clientRecId||'', clientName:src.clientName||'', row:(j.fields||j) } });
}
// No ready rows: emit one placeholder so the chain reaches Build Client Log and the run still writes its row.
if(!out.length) return [{ json: { _empty:true } }];
return out;

// Route Rows: one enroll per row the LinkedIn view handed us. The view decides which rows go
// (Operator-owned filters, nothing in code); this node only refuses what cannot be enrolled and
// never enrolls a row already stamped for this channel, so a loose view cannot double-enroll.
//
// Sent on every add, the same names on every sequencer, only when the row carries a value:
// identity (first_name, last_name, company, company_website, email, linkedin_url) plus the
// standard variables in VARS. The campaign copy picks from them; nothing per play to configure.
const VARS={ title:'Title', seniority:'Seniority', department:'Department', job_title:'Job Title', job_link:'Job Link', job_posted:'Job Posted', job_description:'Job Description', job_applicants:'Job Applicants', job_salary:'Job Salary', existing_in_role:'Existing In Role', icp_reason:'ICP Reason', company_description:'Description', industry_groups:'Industry Groups', employees:'Employees', revenue_range:'Revenue Range', company_city:'Company City', company_state:'Company State', country:'Country', event_type:'Event Type', signal_detail:'Signal Detail', sourced_at:'detected_at' };
const val=(f,k)=>{ const v=f[k]; if(v===undefined||v===null) return ''; if(typeof v==='object') return Array.isArray(v)?v.join(', '):String(v.name||''); return String(v).trim(); };
const out=[];
for(const it of $input.all()){
  const p=it.json||{};
  if(!p.recordId) continue;
  const f=p.row||{};
  const url=val(f,'LinkedIn Campaign');
  const email=val(f,'Final Email');
  const linkedinUrl=val(f,'LinkedIn URL');
  const name=val(f,'Name')||email||linkedinUrl;
  const base={ recordId:p.recordId, baseId:p.baseId, tableId:p.tableId, clientRecId:p.clientRecId, clientName:p.clientName, name };
  if(val(f,'LinkedIn Routed At')) continue; // already stamped for this channel: the view is loose, not the row
  if(!/^https?:\/\//i.test(url)){ out.push({ json: Object.assign({ action:'failed_precheck', reason:'LinkedIn Campaign is not a valid URL' },base) }); continue; }
  if(!val(f,'first_name')||!val(f,'last_name')){ out.push({ json: Object.assign({ action:'failed_precheck', reason:'first_name / last_name missing' },base) }); continue; }
  if(!email&&!linkedinUrl){ out.push({ json: Object.assign({ action:'no_email' },base) }); continue; }
  const otherDone=!val(f,'Email Campaign')||!!val(f,'Email Routed At');
  const dom=val(f,'Domain');
  const extra={};
  for(const [k,col] of Object.entries(VARS)){ const v=val(f,col); if(v) extra[k]=v.length>4000?v.slice(0,4000):v; }
  const body={ firstName:val(f,'first_name'), lastName:val(f,'last_name'), company:val(f,'Company'), extraInfoData:extra };
  if(dom) body.companyWebsite=/^https?:\/\//i.test(dom)?dom:'https://'+dom;
  if(email) body.email=email;
  if(linkedinUrl) body.linkedinUrl=linkedinUrl;
  out.push({ json: Object.assign({ action:'enroll', otherDone, campaign_url:url, enroll_body:body },base) });
}
return out;

const enrolls=$input.all();
let resolved=[]; try{ resolved=$('Route Rows').all().map(i=>i.json).filter(r=>r&&r.action==='enroll'); }catch(e){}
const out=[];
for(let i=0;i<enrolls.length;i++){
  const e=(enrolls[i]&&enrolls[i].json)||{};
  const r=resolved[i]||{};
  if(!r.recordId) continue;
  const ok=!(e&&e.error);
  out.push({ json: {
    recordId:r.recordId, baseId:r.baseId, tableId:r.tableId, clientRecId:r.clientRecId, clientName:r.clientName, name:r.name, otherDone:!!r.otherDone,
    ok: ok,
    reason: ok?'':String((e.error&&(e.error.message||e.error))||'enroll failed after retries').slice(0,160)
  }});
}
return out;

const sd2=$getWorkflowStaticData('global'); const rs=sd2.runStartedAt||0;
let tables=[]; try{ tables=$('Parse Client Config').all().map(i=>i.json).filter(t=>t&&t.baseId); }catch(e){}
const clientRecId=(tables[0]&&tables[0].clientRecId)||'';
const clientName=(tables[0]&&tables[0].clientName)||'';
let prep=[]; try{ prep=$('Prep Rows').all().map(i=>i.json); }catch(e){}
const ready=prep.filter(r=>r&&r.recordId).length;
const readErrors=prep.filter(r=>r&&r._readError).map(r=>({ name:'table '+(r.tableId||'?')+': read failed', reason:r.errorMessage||'' }));
let routes=[]; try{ routes=$('Route Rows').all().map(i=>i.json).filter(r=>r&&r.recordId); }catch(e){}
let results=[]; try{ results=$('Stamp Results').all().map(i=>i.json); }catch(e){}
const ok=results.filter(r=>r.ok);
const failed=results.filter(r=>!r.ok).concat(routes.filter(r=>r.action==='failed_precheck')).concat(readErrors);
const noEmail=routes.filter(r=>r.action==='no_email');
const byTable={};
for(const t of tables){ byTable[t.tableId]={ ready:0, enrolled:0, failed:0, noEmail:0 }; }
for(const r of routes){ const b=byTable[r.tableId]||(byTable[r.tableId]={ready:0,enrolled:0,failed:0,noEmail:0}); b.ready++; if(r.action==='no_email')b.noEmail++; if(r.action==='failed_precheck')b.failed++; }
for(const r of results){ const b=byTable[r.tableId]||(byTable[r.tableId]={ready:0,enrolled:0,failed:0,noEmail:0}); if(r.ok)b.enrolled++; else b.failed++; }
const nf=(x)=>Number(x||0).toLocaleString('en-US');
const parts=['**'+nf(ready)+' ready, '+nf(ok.length)+' enrolled, '+failed.length+' failed**'];
if(!tables.length) parts.push('No usable Intent Tables lines (need tbl ids + Clayroots Base ID on the row); nothing to do.');
const tLines=Object.keys(byTable).map(tid=>{ const b=byTable[tid]; return '- **'+tid+':** '+nf(b.ready)+' ready · '+nf(b.enrolled)+' enrolled · '+nf(b.failed)+' failed · '+nf(b.noEmail)+' no email'; });
if(tLines.length) parts.push('**Tables**\n'+tLines.join('\n'));
if(failed.length) parts.push('**FAILED ('+failed.length+')**\n'+failed.slice(0,5).map(f=>'- '+(f.name||f.recordId||'?')+': '+(f.reason?String(f.reason).slice(0,120):'enroll failed')).join('\n')+(failed.length>5?'\n- ...and '+(failed.length-5)+' more':''));
if(noEmail.length) parts.push('**Skipped ('+noEmail.length+', no email)**\n'+noEmail.map(r=>r.name||r.recordId||'?').join(', '));
const launch=sd2.launch||{};
if(!Array.isArray(sd2.intentResults)) sd2.intentResults=[];
sd2.intentResults.push({client:clientName, ready, enrolled:ok.length, failed:failed.length, target:tables.map(t=>t.tableId).join(', ')});
const row={
 'Automation':'Add Intent Leads to Alta',
 'Status': failed.length ? 'Succeeded with errors' : 'Succeeded',
 'Run at': $now.toISO(),
 'Records In': ready,
 'Records Out': ok.length,
 'Errors': failed.length,
 'Target': tables.map(t=>t.tableId).join(', '),
 'Trigger': launch.trigger||'schedule',
 'Execution ID': String($execution.id)+'-'+(clientRecId||'x'),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': parts.join('\n\n')
};
if(clientRecId) row['Client']=[clientRecId];
return [{json:row}];

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];

const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
sd.intentResults=[];
// Scheduled runs enroll for every client with Intent Tables. A launched run with a Client on its launch row serves that client only.
const cf=String((sd.launch||{}).clientFilter||'');
const all=$input.all().filter(it=>it.json&&it.json.id);
const picked=cf?all.filter(it=>it.json.id===cf):all;
sd.syncScope=cf?(picked.length?'one client (on demand)':'client filter matched no Intent client'):'all clients';
// Nothing to loop over: emit one placeholder so the Any Clients? gate can route straight to the launch-row close.
if(!picked.length) return [{ json: { _empty:true } }];
return picked;

// Closes the Hub launch row of an on-demand run with a roll-up of the per-client rows.
// A scheduled run has no launch row and this leg emits nothing.
const sd=$getWorkflowStaticData('global');
const launch=sd.launch||{};
if(!launch.recordId) return [];
const rs=sd.runStartedAt||launch.startedAt||$now.toMillis();
const results=sd.intentResults||[];
const ready=results.reduce((s,r)=>s+(r.ready||0),0);
const enrolled=results.reduce((s,r)=>s+(r.enrolled||0),0);
const failed=results.reduce((s,r)=>s+(r.failed||0),0);
const lines=results.map(r=>'- **'+(r.client||'?')+':** '+(r.ready||0)+' ready · '+(r.enrolled||0)+' enrolled · '+(r.failed||0)+' failed');
const parts=['**'+results.length+' client(s), '+ready+' ready, '+enrolled+' enrolled, '+failed+' failed**','**Scope:** '+(sd.syncScope||'all clients')];
if(lines.length) parts.push('**Clients** (one detail row per client below this one)\n'+lines.join('\n'));
if(launch.clientFilter && !results.length) parts.push('**Skipped (1, client filter matched no Intent client)**');
const row={
  'Automation': $workflow.name,
  'Status': failed?'Succeeded with errors':'Succeeded',
  'Run at': $now.toISO(),
  'Records In': ready,
  'Records Out': enrolled,
  'Errors': failed,
  'Target': results.map(r=>r.target||'').filter(Boolean).join(', '),
  'Trigger': 'form',
  'Execution ID': String($execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Duration s': Math.round(($now.toMillis()-rs)/1000),
  'Description': parts.join('\n\n')
};
if(launch.clientFilter) row['Client']=[launch.clientFilter];
return [{json:row}];
